import{_ as a,C as s,o as r,c as n,E as d,a3 as o}from"./chunks/framework.CnxW2X0z.js";const i="/versions/v0.19.93/screens/devices/note-range-filter.png",v=JSON.parse('{"title":"Note Range Filter","description":"","frontmatter":{"title":"Note Range Filter","pageClass":"device-doc"},"headers":[],"relativePath":"devices/note-range-filter.md","filePath":"devices/note-range-filter.md"}'),h={name:"devices/note-range-filter.md"};function l(g,t,c,p,m,b){const e=s("DeviceHeading");return r(),n("div",null,[d(e,{slug:"note-range-filter",title:"Note Range Filter"}),t[0]||(t[0]=o('<p>Filter by note range</p><p><img src="'+i+'" alt="Note Range Filter parameters" class="screen"></p><p>The right side draws the 0–127 note range as a track. A solid line passes, a dotted line is blocked. Bright markers sit at <strong>RNG START</strong> and <strong>RNG END</strong>, with their note names above. With <strong>IN-RANGE</strong> set to <strong>DROP</strong>, the window between the markers is dotted; with <strong>KEEP</strong> it is solid. When RNG START is above RNG END, the window wraps around the ends. Messages that are not notes always pass.</p><p>A small pointer under the track shows the last note received. The <strong>LAST</strong> line names it: bright when it passed, dim when it was blocked.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Add <strong>Note Range Filter</strong> to <strong>keep or drop notes inside a pitch window</strong> — split keyboard zones or remove accidental low/high notes.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>0 – 1</td><td>When on, the device is disabled and MIDI passes through unchanged.</td></tr><tr><td>IN-RANGE</td><td>0 – 1</td><td>What happens to notes <strong>inside</strong> the range: <strong>KEEP</strong> passes them and blocks the rest; <strong>DROP</strong> removes them and passes the rest.</td></tr><tr><td>RNG START</td><td>0 – 127</td><td>Low end of the filter range (inclusive note number).</td></tr><tr><td>RNG END</td><td>0 – 127</td><td>High end of the filter range (inclusive note number). When start is greater than end, the range wraps (e.g. 100–10 includes notes 100–127 and 0–10).</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Device is bypassed; messages pass through unchanged.</td></tr></tbody></table><h3 id="in-range" tabindex="-1">IN-RANGE <a class="header-anchor" href="#in-range" aria-label="Permalink to &quot;IN-RANGE&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>KEEP</td><td>Pass notes inside the range; block outside.</td></tr><tr><td style="text-align:right;">1</td><td>DROP</td><td>Remove notes inside the range; pass outside.</td></tr></tbody></table>',13))])}const N=a(h,[["render",l]]);export{v as __pageData,N as default};
